def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    # Fill the diagonal segment connecting the two 1 endpoints; a 6 lying
    # on that diagonal identifies the crossing diagonal to extend in color 6.
    if len(ones) == 2:
        (r1, c1), (r2, c2) = ones
        dr = 1 if r2 > r1 else -1
        dc = 1 if c2 > c1 else -1
        if abs(r2-r1) == abs(c2-c1):
            for k in range(abs(r2-r1)+1):
                out[r1+dr*k][c1+dc*k] = 1
            for r, c in sixes:
                if abs(r-r1) == abs(c-c1) and (r-r1)*(r2-r1) >= 0 and (c-c1)*(c2-c1) >= 0:
                    # Extend the other diagonal through this 6 marker.
                    for rr in range(h):
                        cc = c + (rr-r) * (-1 if dr == dc else 1)
                        if 0 <= cc < w:
                            out[rr][cc] = 6
    return out
